import type { ChatProvider } from '@xsai-ext/providers/utils'
import type { Message } from '@xsai/shared-chat'

import { dualTextChatSystemPrompt } from '../../stores/chat/dual-text'
import { fetchNanobot, nanobotFetchUsesElectronBridge } from './providers/nanobot/fetch'
import { buildNanobotSessionId, resolveNanobotApiBaseUrl } from './providers/nanobot/shared'
import { buildOpenClawSessionHeaders } from './providers/openclaw/shared'

export interface ChatProviderAdapterRequestContext {
  activeSessionId?: string
  providerConfig: Record<string, unknown>
  providerId?: string
  sessionId: string
}

export interface ChatProviderAdapterStreamContext {
  abortSignal?: AbortSignal
  chatProvider: ChatProvider
  headers?: Record<string, string>
  messages: Message[]
  model: string
  onText: (text: string) => Promise<void> | void
  providerConfig: Record<string, unknown>
  providerId?: string
  sessionId: string
}

function debugNanobotTiming(label: string, details: Record<string, unknown>) {
  if (!import.meta.env.DEV)
    return

  console.debug(`[nanobot-timing] ${label}`, details)
}

function resolveAiriPlatform() {
  const hasDesktopPlatform = typeof window !== 'undefined' && 'platform' in window && typeof window.platform === 'string'
  return hasDesktopPlatform ? 'desktop' : 'web'
}

function normalizeNanobotMessageContent(content: Message['content']): string {
  if (typeof content === 'string') {
    const trimmed = content.trim()
    return trimmed
  }

  if (!Array.isArray(content)) {
    throw new TypeError('Nanobot adapter only supports text-based chat messages.')
  }

  if (content.some(part => part?.type === 'image_url')) {
    throw new Error('Nanobot adapter does not support image attachments yet.')
  }

  const text = content
    .map(part => ('text' in part && typeof part.text === 'string' ? part.text : ''))
    .join('')
    .trim()

  return text
}

function buildNanobotMessages(messages: Message[]) {
  const supportedRoles = new Set(['system', 'user', 'assistant'])
  const normalizedMessages = messages
    .filter(message => supportedRoles.has(message.role))
    .map((message) => {
      const content = normalizeNanobotMessageContent(message.content)
      return {
        content,
        role: message.role,
      }
    })
    .filter(message => message.content.length > 0)

  if (!normalizedMessages.some(message => message.role === 'user')) {
    throw new Error('Nanobot adapter requires at least one user message.')
  }

  return normalizedMessages
}

function buildNanobotResponseFormat(messages: Array<{ content: string, role: string }>) {
  const hasDualTextPrompt = messages.some(message =>
    message.role === 'system' && message.content.trim() === dualTextChatSystemPrompt,
  )

  if (!hasDualTextPrompt) {
    return undefined
  }

  return {
    type: 'json_schema',
    json_schema: {
      name: 'dual_text',
      schema: {
        type: 'object',
        properties: {
          display_text: { type: 'string' },
          speech_text: { type: 'string' },
        },
        required: ['display_text', 'speech_text'],
      },
    },
  }
}

async function readNanobotEventStream(
  response: Response,
  onText: (text: string) => Promise<void> | void,
) {
  const reader = response.body?.getReader()
  if (!reader) {
    throw new TypeError('Nanobot returned a streaming response without a readable body.')
  }

  const decoder = new TextDecoder()
  let buffer = ''

  const processBuffer = async (flush = false) => {
    const separator = '\n\n'
    while (true) {
      const index = buffer.indexOf(separator)
      if (index === -1) {
        break
      }

      const rawEvent = buffer.slice(0, index)
      buffer = buffer.slice(index + separator.length)

      const dataLines = rawEvent
        .split('\n')
        .filter(line => line.startsWith('data:'))
        .map(line => line.slice(5).trim())

      if (dataLines.length === 0) {
        continue
      }

      const data = dataLines.join('\n')
      if (data === '[DONE]') {
        return true
      }

      const payload = JSON.parse(data) as {
        choices?: Array<{
          delta?: {
            content?: string
          }
        }>
        error?: {
          message?: string
        }
      }

      if (payload.error?.message) {
        throw new Error(`Nanobot streaming request failed: ${payload.error.message}`)
      }

      const delta = payload.choices?.[0]?.delta?.content
      if (typeof delta === 'string' && delta.length > 0) {
        await onText(delta)
      }
    }

    if (flush && buffer.trim()) {
      throw new Error('Nanobot returned an incomplete SSE event stream.')
    }

    return false
  }

  while (true) {
    const { done, value } = await reader.read()
    buffer += decoder.decode(value || new Uint8Array(), { stream: !done })
    const sawDone = await processBuffer(done)
    if (done || sawDone) {
      break
    }
  }
}

async function streamWithNanobotAdapter(context: ChatProviderAdapterStreamContext) {
  const requestStartedAt = performance.now()
  const baseUrl = resolveNanobotApiBaseUrl(typeof context.providerConfig.baseUrl === 'string' ? context.providerConfig.baseUrl : undefined)
  const apiKey = typeof context.providerConfig.apiKey === 'string' && context.providerConfig.apiKey.trim()
    ? context.providerConfig.apiKey.trim()
    : 'dummy'
  const model = context.model.trim() || (typeof context.providerConfig.model === 'string' ? context.providerConfig.model.trim() : '')

  if (!model) {
    throw new Error('Nanobot model is not configured. Set a model in provider settings or choose one in Consciousness.')
  }
  const sessionId = buildNanobotSessionId({
    fallbackSessionId: context.sessionId,
    platform: resolveAiriPlatform(),
    sessionId: typeof context.providerConfig.sessionId === 'string' ? context.providerConfig.sessionId : undefined,
    sessionIdStrategy: context.providerConfig.sessionIdStrategy === 'manual' ? 'manual' : 'auto',
  })
  const nanobotMessages = buildNanobotMessages(context.messages)
  const responseFormat = buildNanobotResponseFormat(nanobotMessages)
  const stream = !nanobotFetchUsesElectronBridge()

  const response = await fetchNanobot(`${baseUrl}/chat/completions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      ...context.headers,
    },
    body: JSON.stringify({
      model,
      messages: nanobotMessages,
      response_format: responseFormat,
      session_id: sessionId,
      stream,
    }),
    signal: context.abortSignal,
  })

  debugNanobotTiming('request-finished-headers', {
    durationMs: Math.round(performance.now() - requestStartedAt),
    sessionId: context.sessionId,
    status: response.status,
    stream,
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Nanobot chat request failed with HTTP ${response.status}${errorText ? `: ${errorText}` : '.'}`)
  }

  const contentType = response.headers.get('content-type') || ''
  if (contentType.includes('text/event-stream')) {
    let sawFirstChunk = false
    await readNanobotEventStream(response, async (text) => {
      if (!sawFirstChunk) {
        sawFirstChunk = true
        debugNanobotTiming('first-text-chunk', {
          durationMs: Math.round(performance.now() - requestStartedAt),
          preview: text.slice(0, 40),
          sessionId: context.sessionId,
        })
      }
      await context.onText(text)
    })
    debugNanobotTiming('stream-complete', {
      durationMs: Math.round(performance.now() - requestStartedAt),
      sessionId: context.sessionId,
    })
    return
  }

  const payload = await response.json().catch(() => null) as any
  const content = payload?.choices?.[0]?.message?.content
  if (typeof content !== 'string') {
    throw new TypeError('Nanobot returned an invalid response payload: expected `choices[0].message.content` to be a string.')
  }

  debugNanobotTiming('json-response-complete', {
    durationMs: Math.round(performance.now() - requestStartedAt),
    preview: content.slice(0, 80),
    sessionId: context.sessionId,
  })
  await context.onText(content)
}

export function buildProviderRequestHeaders(context: ChatProviderAdapterRequestContext): Record<string, string> {
  if (context.providerId === 'openclaw') {
    const headers = buildOpenClawSessionHeaders({
      activeSessionId: context.activeSessionId,
      fallbackSessionId: context.sessionId,
      sessionKey: typeof context.providerConfig.sessionKey === 'string' ? context.providerConfig.sessionKey : undefined,
      sessionStrategy: context.providerConfig.sessionStrategy === 'manual' ? 'manual' : 'auto',
    })

    const underlyingModel = typeof context.providerConfig.underlyingModel === 'string'
      ? context.providerConfig.underlyingModel.trim()
      : ''
    if (underlyingModel) {
      headers['x-openclaw-model'] = underlyingModel
    }

    return headers
  }

  return {}
}

export function providerHandlesStreaming(providerId?: string): boolean {
  return providerId === 'nanobot'
}

export async function streamThroughProviderAdapter(context: ChatProviderAdapterStreamContext): Promise<boolean> {
  if (context.providerId === 'nanobot') {
    await streamWithNanobotAdapter(context)
    return true
  }

  return false
}
