export interface DualTextChatResult {
  displayText?: string
  speechText?: string
}

export interface PartialDualTextChatResult {
  displayText?: string
  speechText?: string
}

export const dualTextChatSystemPrompt = [
  'You are preparing AIRI dialogue for dual-text speech output.',
  'Return valid JSON only.',
  'Use this exact schema: {"display_text":"...","speech_text":"..."}',
  'Rules:',
  '- display_text must be natural Traditional Chinese for on-screen display.',
  '- speech_text must be natural Japanese for speech synthesis.',
  '- display_text and speech_text must have the same meaning.',
  '- Keep the character voice and tone consistent.',
  '- Do not include markdown, code fences, explanations, or extra keys.',
].join('\n')

function stripCodeFence(input: string): string {
  const trimmed = input.trim()
  if (!trimmed.startsWith('```'))
    return trimmed

  return trimmed
    .replace(/^```[\w-]*\n?/, '')
    .replace(/\n?```$/, '')
    .trim()
}

function decodeJsonStringFragment(input: string): string {
  let result = ''

  for (let index = 0; index < input.length; index += 1) {
    const char = input[index]
    if (char !== '\\') {
      result += char
      continue
    }

    const next = input[index + 1]
    if (next == null) {
      break
    }

    switch (next) {
      case '"':
      case '\\':
      case '/':
        result += next
        index += 1
        break
      case 'b':
        result += '\b'
        index += 1
        break
      case 'f':
        result += '\f'
        index += 1
        break
      case 'n':
        result += '\n'
        index += 1
        break
      case 'r':
        result += '\r'
        index += 1
        break
      case 't':
        result += '\t'
        index += 1
        break
      case 'u': {
        const codePoint = input.slice(index + 2, index + 6)
        if (/^[0-9a-f]{4}$/i.test(codePoint)) {
          result += String.fromCharCode(Number.parseInt(codePoint, 16))
          index += 5
          break
        }
        result += next
        index += 1
        break
      }
      default:
        result += next
        index += 1
        break
    }
  }

  return result
}

export function extractPartialDualTextChatResult(input: string): PartialDualTextChatResult | null {
  const normalized = stripCodeFence(input)
  if (!normalized) {
    return null
  }

  const displayMatch = normalized.match(/"display_text"\s*:\s*"((?:\\.|[^"\\])*)/s)
  const speechMatch = normalized.match(/"speech_text"\s*:\s*"((?:\\.|[^"\\])*)/s)

  const displayText = displayMatch
    ? decodeJsonStringFragment(displayMatch[1]).trim()
    : ''
  const speechText = speechMatch
    ? decodeJsonStringFragment(speechMatch[1]).trim()
    : ''

  if (!displayText && !speechText) {
    return null
  }

  const result: PartialDualTextChatResult = {}
  if (displayText)
    result.displayText = displayText
  if (speechText)
    result.speechText = speechText
  return result
}

export function parseDualTextChatResult(input: string): DualTextChatResult | null {
  const normalized = stripCodeFence(input)
  if (!normalized)
    return null

  try {
    const parsed = JSON.parse(normalized) as {
      display_text?: unknown
      speech_text?: unknown
      displayText?: unknown
      speechText?: unknown
    }

    const displayText = typeof parsed.display_text === 'string'
      ? parsed.display_text.trim()
      : typeof parsed.displayText === 'string'
        ? parsed.displayText.trim()
        : ''
    const speechText = typeof parsed.speech_text === 'string'
      ? parsed.speech_text.trim()
      : typeof parsed.speechText === 'string'
        ? parsed.speechText.trim()
        : ''

    if (!displayText && !speechText)
      return null

    return {
      displayText: displayText || undefined,
      speechText: speechText || undefined,
    }
  }
  catch {
    return null
  }
}
